# Bounded readback for Chapters 7–8. Run from the repository root.
# Source calculations are preserved; only planning summaries are written here.
library(jsonlite)
library(digest)
out <- 'docs/thesis_design/sections/concessionality_results/prose_20260922'
run <- fromJSON('data-derived/p15_master/current_run.json')
inputs <- c('data-derived/p15_master/current_run.json')
read_stage <- function(stage, name) {
  p <- file.path(run$stages[[stage]]$dir, name)
  inputs <<- unique(c(inputs,p))
  read.csv(p, check.names=FALSE, stringsAsFactors=FALSE)
}
checks <- data.frame(check=character(), passed=logical())
check <- function(name, condition) {
  checks <<- rbind(checks,data.frame(check=name,passed=isTRUE(condition)))
  stopifnot(isTRUE(condition))
}
save <- function(x,name) write.csv(x,file.path(out,name),row.names=FALSE,na='')
crs <- read_stage('crs_modern_summary','modern_matched_financing_records.csv')
x <- crs[crs$non_peer,]
summary <- read_stage('crs_modern_summary','modern_summary.csv')
a <- subset(summary,benchmark_view=='non_peer' & weighting=='financing_record_equal')
check('CRS main count',nrow(x)==1274)
check('CRS mean replay',abs(mean(x$delta_standardized_ge_pp)-a$mean_market_minus_standardized_ge_pp)<1e-9)
check('CRS weighted replay',abs(weighted.mean(x$delta_standardized_ge_pp,x$amount_usd)-subset(summary,benchmark_view=='non_peer' & weighting=='nominal_USD_commitment')$mean_market_minus_standardized_ge_pp)<1e-9)
d <- data.frame(records=nrow(x),median_gap=median(x$delta_standardized_ge_pp),mean_absolute_gap=mean(abs(x$delta_standardized_ge_pp)),p10=quantile(x$delta_standardized_ge_pp,.1),p90=quantile(x$delta_standardized_ge_pp,.9),positive_gap_count=sum(x$delta_standardized_ge_pp>0),positive_gap_pct=100*mean(x$delta_standardized_ge_pp>0))
save(d,'crs_distribution.csv')
save(summary,'crs_modern_views.csv')
