replay <- do.call(rbind,lapply(split(y,y$analysis_year),function(z)data.frame(year=z$analysis_year[1],n=nrow(z),market_ge_change=mean(z$market_ge_change),benchmark=mean(z$benchmark_component),terms=mean(z$terms_component),gap_change=mean(z$discrepancy_change))))
