for(i in seq_len(nrow(replay))){s<-subset(saved,evidence_view=='without_peers' & analysis_year==replay$year[i]);check(paste('Non-peer year replay',replay$year[i]),s$n==replay$n[i] && abs(s$market_ge_change-replay$market_ge_change[i])<1e-8)}
save(replay,'nonpeer_temporal_components.csv')
three <- read_stage('pv_three_block','three_block_case_decomposition.csv')
check('Every three-part decomposition adds',max(abs(three$market_ge_change-three$benchmark_component-three$official_interest_component-three$maturity_grace_component))<1e-8)
ib <- subset(three,creditor=='IBRD' & analysis_year==2023)
is <- read_stage('pv_three_block','three_block_creditor_year.csv')
check('IBRD component replay',nrow(ib)==36 && abs(mean(ib$official_interest_component)-subset(is,creditor=='IBRD' & analysis_year==2023)$official_interest_component)<1e-8)
save(subset(is,creditor=='IBRD' & analysis_year %in% c(2022,2023)),'ibrd_components.csv')
