save(subset(fixed,dataset=='add' & support=='method_available_on_main_nonpeer_loans'),'add_fixed_method.csv')
pairs <- read_stage('pv_interpretation','matched_creditor_pairs.csv')
rev <- subset(pairs,interest_ranking_reversed)
check('Full reversal count',nrow(pairs)==209 && nrow(rev)==19)
check('Non-peer reversal count',sum(pairs$selected_tier!='peer')==177 && sum(rev$selected_tier!='peer')==17)
save(data.frame(view=c('all_selected','non_peer'),pairs=c(nrow(pairs),sum(pairs$selected_tier!='peer')),reversals=c(nrow(rev),sum(rev$selected_tier!='peer')),median_reversal_gap=c(median(abs(rev$ge_difference_a_minus_b)),median(abs(rev$ge_difference_a_minus_b[rev$selected_tier!='peer'])))),'reversal_summary.csv')
