loan <- read_stage('loan_comparisons','comparison_summary.csv');save(subset(loan,main_cohort & benchmark_view=='non_peer'),'loan_comparisons.csv')
cp <- read_stage('loan_comparisons','creditor_pair_summary.csv');save(subset(cp,dataset=='mpg'),'mpg_creditor_pairs.csv')
# Register additional inspected context used in the content plan.
for (item in list(c('loan_period_inference','primary_country_inference.csv'),c('loan_period_inference','common_country_period_contrasts.csv'),c('pv_followup','ibrd_interest_step_summary.csv'),c('pv_three_block','ibrd_cancellation_check.csv'),c('pv_interpretation','matched_creditor_summary.csv'),c('crs_modern_summary','annual_summary.csv'),c('loan_comparisons','sample_restriction_at5.csv'),c('crs_application','comparison_summary.csv'),c('loan_period_inference','composition_sensitivities.csv'))) read_stage(item[1],item[2])

