# Matched scales and counts shown separately from the outcome axis.
plotdata$dataset <- factor(plotdata$dataset,levels=c('OECD CRS','African Debt Database'))
bt <- theme_minimal(base_size=11,base_family='serif') + theme(panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(colour='#E5E5E5',linewidth=.3),strip.text=element_text(face='bold',size=11,hjust=0),axis.title=element_text(size=10),plot.margin=margin(7,10,5,7))
xs <- function() scale_x_continuous(breaks=2018:2024,limits=c(2017.65,2024.35),expand=c(0,0))
top <- ggplot(plotdata,aes(year,gap))+geom_hline(yintercept=0,colour='#686868',linewidth=.45)+geom_line(colour='#173F57',linewidth=.8)+geom_point(colour='#173F57',size=1.7)+facet_wrap(~dataset,nrow=1)+xs()+scale_y_continuous(breaks=seq(-20,10,5),limits=c(-20,10),expand=expansion(mult=c(0,.03)))+labs(x=NULL,y='Borrower-rate minus standardized\ngrant element (percentage points)')+bt+theme(axis.text.x=element_blank(),axis.ticks.x=element_blank())
